/** The browser keeps the generated bytes local until the user chooses a destination. */
export type GcodeContent = string | Blob | ArrayBuffer | Uint8Array<ArrayBuffer>;

export interface GcodeExportResult {
  method: 'share' | 'download' | 'cancelled';
  filename: string;
}

/** Keep a real .gcode extension and avoid filesystem/path characters. */
export function gcodeFilename(name = 'K1C-print'): string {
  const leaf = name.split(/[\\/]/).pop() || 'K1C-print';
  const stem = leaf.replace(/\.(?:stl|3mf|obj|gcode|gco|gc)$/i, '')
    .replace(/[\u0000-\u001f\u007f<>:"|?*]/g, '-')
    .replace(/^\.+|[. ]+$/g, '')
    .trim()
    .slice(0, 160) || 'K1C-print';
  return `${stem}.gcode`;
}

export function createGcodeFile(content: GcodeContent, name = 'K1C-print'): File {
  return new File([content], gcodeFilename(name), { type: 'text/plain', lastModified: Date.now() });
}

export function canShareGcode(file: File): boolean {
  if (typeof navigator === 'undefined' || !navigator.share || !navigator.canShare) return false;
  try {
    return navigator.canShare({ files: [file] });
  } catch {
    return false;
  }
}

/** Call directly from a tap; awaiting other work first loses iOS user activation. */
export async function shareGcode(file: File): Promise<GcodeExportResult> {
  if (!canShareGcode(file)) {
    throw new Error('File sharing is unavailable in this browser. Use Download G-code, then move the file to your USB drive in Files.');
  }
  try {
    await navigator.share({ files: [file], title: file.name });
    return { method: 'share', filename: file.name };
  } catch (error) {
    if (error instanceof Error && error.name === 'AbortError') {
      return { method: 'cancelled', filename: file.name };
    }
    throw new Error('The share sheet could not open. Tap Download G-code, then use Files to move it to your USB drive.', { cause: error });
  }
}

/** Reports a requested download, not a confirmed write to the user's filesystem. */
export function downloadGcode(file: File): GcodeExportResult {
  const url = URL.createObjectURL(file);
  const anchor = document.createElement('a');
  anchor.href = url;
  anchor.download = file.name;
  anchor.style.display = 'none';
  document.body.appendChild(anchor);
  anchor.click();
  anchor.remove();
  // Safari may dereference the blob after the click handler completes.
  window.setTimeout(() => URL.revokeObjectURL(url), 60_000);
  return { method: 'download', filename: file.name };
}

/** Preferred iPhone path: share sheet → Save to Files → USB under Locations. */
export async function exportGcode(content: GcodeContent, name = 'K1C-print'): Promise<GcodeExportResult> {
  const file = createGcodeFile(content, name);
  return canShareGcode(file) ? shareGcode(file) : downloadGcode(file);
}
